<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Harbor Storage</title><style>body{margin:0;background:#091827;color:#dbeafe;font:15px system-ui}main{max-width:1120px;margin:auto;padding:40px 24px}header{display:flex;justify-content:space-between;align-items:center;gap:16px}h1{font-size:34px;margin:0}.muted{color:#93a4b8}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin:28px 0}.card{padding:20px;background:#10263a;border:1px solid #24445f;border-radius:12px}.number{font-size:30px;color:#67e8f9;font-weight:700}.split{display:grid;grid-template-columns:1fr 1fr;gap:16px}input,button{border-radius:7px;padding:10px;border:1px solid #355b79}button{background:#2563eb;color:#fff;border:0;font-weight:700}.danger{background:#7f1d1d}.flash{background:#164e63;padding:14px;border-radius:8px;word-break:break-all}table{width:100%;border-collapse:collapse}td,th{padding:10px 4px;border-bottom:1px solid #24445f;text-align:left}@media(max-width:720px){.split{grid-template-columns:1fr}}</style></head><body><main><header><div><p class="muted">Harbor Storage / control room</p><h1>Object storage on this server.</h1></div><form method="post" action="/logout">@csrf<button>Sign out</button></form></header>@if(session('created_secret'))<p class="flash">Access key: <b>{{ session('created_secret')[0] }}</b><br>Secret: <b>{{ session('created_secret')[1] }}</b><br>Copy the secret now. It will not be shown again.</p>@endif<div class="grid"><div class="card"><span class="number">{{ $buckets }}</span><br>Buckets</div><div class="card"><span class="number">{{ $objects }}</span><br>Active objects</div><div class="card"><span class="number">{{ number_format($bytes) }}</span><br>Bytes stored</div></div><div class="split"><section class="card"><h2>Create API key</h2><form method="post" action="/keys">@csrf<label><input type="checkbox" name="scopes[]" value="read" checked> Read</label><label><input type="checkbox" name="scopes[]" value="write" checked> Write</label><label><input type="checkbox" name="scopes[]" value="delete"> Delete</label><br><button>Create credential</button></form><p class="muted">Endpoint: <code>{{ url('/s3') }}</code></p></section><section class="card"><h2>Recent activity</h2><table>@forelse($events as $event)<tr><td>{{ $event->action }}</td><td>{{ $event->bucket }}</td><td class="muted">{{ $event->created_at->diffForHumans() }}</td></tr>@empty<tr><td class="muted">No storage activity yet.</td></tr>@endforelse</table></section></div><section class="card"><h2>Active credentials</h2><table>@forelse($keys as $key)<tr><td><code>{{ $key->access_key }}</code></td><td>{{ implode(', ', $key->scopes ?: ['*']) }}</td><td><form method="post" action="/keys/{{ $key->id }}">@csrf @method('DELETE')<button class="danger">Revoke</button></form></td></tr>@empty<tr><td class="muted">Create a credential to connect an S3 client.</td></tr>@endforelse</table></section></main></body></html>
